    def handle(self, *args, **options):
        """Execute command"""
        total = len(self.volunteers_data)
        success = 0
        errors = []
        
        self.stdout.write(self.style.SUCCESS(f"\n{'='*80}"))
        self.stdout.write(self.style.SUCCESS(f"Adding {total} volunteers to database (State 7 - Gujarat)"))
        self.stdout.write(self.style.SUCCESS(f"{'='*80}\n"))
        
        for idx, vol_data in enumerate(self.volunteers_data, 1):
            try:
                vol = Volunteer.objects.create(**vol_data)
                success += 1
                self.stdout.write(self.style.SUCCESS(f"✓ [{idx:2d}/{total}] Added: {vol_data['name']:40s} | MIS ID: {vol_data['mis_id']:4d} | District: {vol_data['district_id']}"))
            except Exception as e:
                errors.append({
                    'idx': idx,
                    'name': vol_data['name'],
                    'mis_id': vol_data['mis_id'],
                    'error': str(e)
                })
                self.stdout.write(self.style.ERROR(f"✗ [{idx:2d}/{total}] FAILED: {vol_data['name']:40s} | Error: {str(e)[:60]}"))
        
        # Summary
        self.stdout.write(self.style.SUCCESS(f"\n{'='*80}"))
        self.stdout.write(self.style.SUCCESS(f"SUMMARY"))
        self.stdout.write(self.style.SUCCESS(f"{'='*80}"))
        self.stdout.write(self.style.SUCCESS(f"Total Records:  {total}"))
        self.stdout.write(self.style.SUCCESS(f"Successfully Added: {success}"))
        self.stdout.write(self.style.WARNING(f"Errors: {len(errors)}"))
        
        if errors:
            self.stdout.write(self.style.ERROR(f"\n{'='*80}"))
            self.stdout.write(self.style.ERROR(f"ERROR DETAILS"))
            self.stdout.write(self.style.ERROR(f"{'='*80}"))
            for err in errors:
                self.stdout.write(self.style.ERROR(f"\n[{err['idx']}] {err['name']} (MIS ID: {err['mis_id']})"))
                self.stdout.write(self.style.ERROR(f"    Error: {err['error']}"))
        
        if success == total:
            self.stdout.write(self.style.SUCCESS(f"\n✓ ALL RECORDS ADDED SUCCESSFULLY!"))
        else:
            self.stdout.write(self.style.WARNING(f"\n⚠ {len(errors)} records failed to add. Please review errors above."))
        
        self.stdout.write(self.style.SUCCESS(f"\n{'='*80}\n"))
